// The licence files a packaged build must hold (#2126, AC-1 and AC-2), checked by electron-builder's afterPack hook so
// that a package which lost one is not made:
//   - THIRD-PARTY-NOTICES.txt, generated by scripts/moltenterm-notices.mjs and shipped under <resources>/licenses/;
//   - Electron's licence and Chromium's licences, which electron-builder keeps from Electron's own distribution
//     (LICENSE.electron.txt and LICENSES.chromium.html): in the resources folder of the macOS app, next to the executable
//     on Linux and Windows.

const fs = require("fs");
const path = require("path");

const NoticesName = "THIRD-PARTY-NOTICES.txt";
const ElectronLicenseName = "LICENSE.electron.txt";
const ChromiumLicensesName = "LICENSES.chromium.html";

function resourcesDirOf({ platform, appOutDir, productFilename }) {
    return platform === "darwin"
        ? path.join(appOutDir, `${productFilename}.app`, "Contents", "Resources")
        : path.join(appOutDir, "resources");
}

// [{ file, what }]: where each licence file must be, and what it is.
function expectedLicenseFiles(options) {
    const resources = resourcesDirOf(options);
    const electronLicenses = options.platform === "darwin" ? resources : options.appOutDir;
    return [
        { file: path.join(resources, "licenses", NoticesName), what: "the third-party notices (task build:prod, then node scripts/moltenterm-notices.mjs)" },
        { file: path.join(electronLicenses, ElectronLicenseName), what: "Electron's licence" },
        { file: path.join(electronLicenses, ChromiumLicensesName), what: "Chromium's licences" },
    ];
}

function missingLicenseFiles(options) {
    return expectedLicenseFiles(options).filter(({ file }) => {
        try {
            return fs.statSync(file).size === 0;
        } catch {
            return true;
        }
    });
}

// electron-builder's afterPack context: appOutDir, electronPlatformName and the packager.
function verifyPackagedLicenses(context) {
    const missing = missingLicenseFiles({
        platform: context.electronPlatformName,
        appOutDir: context.appOutDir,
        productFilename: context.packager.appInfo.productFilename,
    });
    if (missing.length > 0) {
        const lines = missing.map(({ file, what }) => `  - ${file}: ${what}`);
        // electron-builder keeps Electron's two files when it unpacks Electron's zip; with a custom unpacked distribution
        // (-c.electronDist) it copies only the application, and they are lost.
        throw new Error(
            `The package is missing licence files it must carry:\n${lines.join("\n")}\n` +
                "(electron-builder keeps Electron's licences only when it unpacks Electron's own zip, not with -c.electronDist.)"
        );
    }
}

module.exports = { expectedLicenseFiles, missingLicenseFiles, resourcesDirOf, verifyPackagedLicenses };
